/**
 * ReflectionInput
 * Represents the raw creative thought entering DREVAIA OS.
 * This is the only required input for the Content Transformer.
 */

export interface ReflectionInput {
  /**
   * Unique identifier.
   */
  id: string;

  /**
   * Original reflection written by a human or generated by AI.
   */
  text: string;

  /**
   * Original language (ISO 639-1).
   * Example: "es", "en", "fr", "pt"
   */
  language: string;

  /**
   * Source of the reflection.
   * Examples:
   * - human
   * - ai
   * - imported
   * - api
   */
  source: string;

  /**
   * ISO datetime.
   */
  createdAt: string;
}